53	const PROCESSING_FEE = 5;
54	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
55	const BASE_PREMIUMS: Record<string, number> = {
56	  sword: 100,
57	  amulet: 60,
58	  staff: 80,
59	  potion: 40,
60	  rune: 25,
61	  moonstone: 25,
62	};
