64	const BLOCK_SIZE = 3;
65	const RUNE_BLOCK_PREMIUM = 60;
66	
67	const COMPONENT_TYPES = ["rune", "moonstone"];
68	
69	const blockAdjustment = (items: Item[], componentType: string): number => {
70	  const count = items.filter((item) => item.type === componentType).length;
71	  return count === BLOCK_SIZE
72	    ? RUNE_BLOCK_PREMIUM - BLOCK_SIZE * BASE_PREMIUMS[componentType]
73	    : 0;
74	};
