76	const basePremiumFor = (items: Item[]): number =>
77	  items.reduce((total, item) => total + BASE_PREMIUMS[item.type], 0) +
78	  COMPONENT_TYPES.reduce(
79	    (total, componentType) => total + blockAdjustment(items, componentType),
80	    0,
81	  );
