88	export const runScenario = (scenario: Scenario): ScenarioOutput => {
89	  const quoteStep = scenario.steps[0] as QuoteStep;
90	  return { results: [{ premium: quotePremium(basePremiumFor(quoteStep.items)) }] };
91	};
