const BLOCK_SIZE = 3;
const COMPONENT_BLOCK_PREMIUM = 60;

const COMPONENT_TYPES = ["rune", "moonstone"];

const componentBlockAdjustment = (
  items: Item[],
  componentType: string,
): number => {
  const count = items.filter((item) => item.type === componentType).length;
  return count === BLOCK_SIZE
    ? COMPONENT_BLOCK_PREMIUM - BLOCK_SIZE * BASE_PREMIUMS[componentType]
    : 0;
};

const basePremiumFor = (items: Item[]): number =>
  items.reduce((total, item) => total + BASE_PREMIUMS[item.type], 0) +
  COMPONENT_TYPES.reduce(
    (total, componentType) => total + componentBlockAdjustment(items, componentType),
    0,
  );
